WITH latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY job_title ORDER BY hire_date NULLS LAST, id) AS row_num FROM employees) t WHERE row_num = 1) SELECT id, full_name, email, job_title, salary, hire_date, level, row_num, CASE WHEN job_title RLIKE '^(Analyst|Director)$' THEN 'OTHER_ZONE' WHEN job_title RLIKE '^(Engineer|Manager)$' THEN 'GROUP_B' ELSE 'EXTENDED' END AS job_title_zone FROM latest ORDER BY id
